package com.example.leavemanagement.people.api;
import com.example.leavemanagement.people.application.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin/employees") public class AdminEmployeeController { private final EmployeeAdministrationService service;private final EmployeeAdministrationQueryService query; public AdminEmployeeController(EmployeeAdministrationService s,EmployeeAdministrationQueryService q){service=s;query=q;} @GetMapping public EmployeeAdministrationQueryService.PageView list(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return query.list(page,size);} @PostMapping @ResponseStatus(HttpStatus.CREATED) public EmployeeAdministrationService.View create(@Valid @RequestBody Create c){return service.create(new EmployeeAdministrationService.CreateCommand(c.employeeNumber(),c.displayName(),c.email(),c.login(),c.initialPassword(),c.managerId(),c.roles(),c.active()));} @PatchMapping("/{id}") public EmployeeAdministrationService.View update(@PathVariable UUID id,@Valid @RequestBody Update c){return service.update(id,new EmployeeAdministrationService.UpdateCommand(c.employeeNumber(),c.displayName(),c.email(),c.login(),c.managerId(),c.roles(),c.active(),c.expectedVersion()));} public record Create(@NotBlank @Size(max=64)String employeeNumber,@NotBlank @Size(max=160)String displayName,@NotBlank @Email @Size(max=254)String email,@NotBlank @Size(max=254)String login,@NotBlank @Size(min=12,max=200)String initialPassword,UUID managerId,@NotEmpty List<@NotBlank String> roles,boolean active){} public record Update(@NotBlank @Size(max=64)String employeeNumber,@NotBlank @Size(max=160)String displayName,@NotBlank @Email @Size(max=254)String email,@NotBlank @Size(max=254)String login,UUID managerId,@NotEmpty List<@NotBlank String> roles,boolean active,@NotNull @Min(0)Long expectedVersion){} }
